Here is an example Swift code that retrieves and displays student achievement data from an SQL database and presents it on an HTML webpage:
```
import MySQL
// Connect to the SQL database
let connection = MySQL.Connection(
    host: "localhost",
    user: "username",
    password: "password",
    database: "stem_database"
)
// Retrieve student grades from the SQL database
let query = "SELECT * FROM student_grades"
let results = try connection.execute(query)
// Create an HTML table to display the grades
var htmlTable = "<table><tr><th>Student Name</th><th>Math Grade</th><th>Science Grade</th><th>Technology Grade</th><th>Engineering Grade</th></tr>"
for row in results {
    let studentName = row[0] as! String
    let mathGrade = row[1] as! Int
    let scienceGrade = row[2] as! Int
    let technologyGrade = row[3] as! Int
    let engineeringGrade = row[4] as! Int
    htmlTable += "<tr><td>\(studentName)</td><td>\(mathGrade)</td><td>\(scienceGrade)</td><td>\(technologyGrade)</td><td>\(engineeringGrade)</td></tr>"
}
htmlTable += "</table>"
// Create an advanced line chart to show grade improvement over time
let chart = LineChart()
chart.addLine([3, 5, 6, 7, 8, 9, 10], label: "Math")
chart.addLine([4, 6, 7, 8, 9, 10, 11], label: "Science")
chart.addLine([5, 7, 8, 9, 10, 11, 12], label: "Technology")
chart.addLine([6, 8, 9, 10, 11, 12, 13], label: "Engineering")
let chartHtml = chart.html
// Retrieve media coverage from the SQL database
let mediaQuery = "SELECT * FROM media_coverage WHERE school_name='Loyola High School'"
let mediaResults = try connection.execute(mediaQuery)
// Display media coverage on the webpage
var mediaHtml = "<h2>Media Coverage</h2>"
for row in mediaResults {
    let title = row[0] as! String
    let description = row[1] as! String
    let imageUrl = row[2] as! String
    mediaHtml += "<div><h3>\(title)</h3><p>\(description)</p><img src=\"\(imageUrl)\"></div>"
}
// Combine all HTML elements into a single webpage
let webpage = "<html><head><title>STEM Student Achievements</title><script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script></head><body>\(htmlTable)\(chartHtml)\(mediaHtml)</body></html>"
// Print the webpage to the console
print(webpage)
```
