Sure! Here is a Swift function that decodes the hidden message:
```swift
func decodeMessage(_ input: String) -> String {
    let numbers = input.components(separatedBy: " ").compactMap { Int($0) }
    let alphabet = "abcdefghijklmnopqrstuvwxyz"
    var words: [String] = []

    for number in numbers {
        var powerLevel = 0
        var word = ""

        for letter in alphabet {
            powerLevel += 1

            if powerLevel == number {
                word.append(letter)
                break
            }
        }

        words.append(word)
    }

    let sortedWords = words.sorted { word1, word2 in
        let powerLevel1 = powerLevel(for: word1)
        let powerLevel2 = powerLevel(for: word2)
        return powerLevel1 > powerLevel2
    }

    let decodedMessage = sortedWords.reduce("") { result, word in
        result + String(word.first!)
    }

    return decodedMessage
}
func powerLevel(for word: String) -> Int {
    let alphabet = "abcdefghijklmnopqrstuvwxyz"
    var powerLevel = 0

    for letter in word {
        let position = alphabet.firstIndex(of: letter)! // force unwrap since we know the letter is in the alphabet
        powerLevel += (alphabet.distance(from: alphabet.startIndex, to: position) + 1)
    }

    return powerLevel
}
```
You can call this function with the input string "7 15 21 12 4 20 19 9 14 7 20 18 1 3 20 9 15 14" to get the decoded message. The function works by first splitting the input string into an array of integers, then using the provided formula to generate a list of words. It then sorts the words by power level, and finally concatenates the first letter of each word to form the decoded message.

