// SQLDatabase.java
import java.sql.*;
public class SQLDatabase {
    private Connection connection;
    private Statement statement;
    public SQLDatabase() {
        try {
            connection = DriverManager.getConnection("jdbc:mysql://localhost:3306/surveydata", "root", "");
            statement = connection.createStatement();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
    public void addData(SurveyQuestions[] questions) {
        try {
            String query = "INSERT INTO surveydata (question, answer) VALUES (?, ?)";
            PreparedStatement preparedStatement = connection.prepareStatement(query);
            for (SurveyQuestions q : questions) {
                preparedStatement.setString(1, q.getQuestion());
                preparedStatement.setInt(2, q.getAnswer());
                preparedStatement.executeUpdate();
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
    public void close() {
        try {
            statement.close();
            connection.close();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
