Here's the initial code in Swift that calculates the sum of even numbers between two given numbers using loops:
func sumOfEvenNumbersBetween(start: Int, end: Int) -> Int {
    var sum = 0

    for num in start...end {
        if num % 2 == 0 {
            sum += num
        }
    }

    return sum
