% Load the dataset into a table
data = readtable('employee_data.csv');
% Filter the dataset based on the given criteria
filtered_data = data(data.Age >= 25 & data.Age <= 50 & data.NumJobs >= 2 & data.GPA >= 3.5 & data.Certifications > 0 & data.PerformanceRating >= 4 & data.CommunityProject == true, :);
% Group the filtered data by age group and leadership qualities
age_groups = splitapply(@(x){x}, filtered_data, categorical(floor((filtered_data.Age - 25) / 10) * 10 + 25));
leadership_groups = splitapply(@(x){x}, filtered_data, categorical(filtered_data.Leadership == true));
% Identify the top 10 candidates from each age group and leadership group
top_candidates = table();
for i = 1:numel(age_groups)
    for j = 1:numel(leadership_groups)
        candidates = intersect(age_groups{i}, leadership_groups{j});
        if numel(candidates) >= 10
            candidates = candidates(randperm(numel(candidates)));
            top_candidates = [top_candidates; candidates(1:10)];
        end
    end
end
% Display the top 10 candidates
disp(top_candidates);
```
