Here is the C++ code to arrange the given number 4759 in ascending order such that the difference between any two consecutive numbers is a prime number:
```
#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;
bool isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    for (int i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}
int main() {
    int n = 4759;
    vector<int> digits;
    while (n > 0) {
        digits.push_back(n % 10);
        n /= 10;
    }
    sort(digits.begin(), digits.end());
    do {
        bool valid = true;
        for (int i = 1; i < digits.size(); i++) {
            if (!isPrime(digits[i] - digits[i-1])) {
                valid = false;
                break;
            }
        }
        if (valid) {
            for (int i = digits.size() - 1; i >= 0; i--) {
                cout << digits[i];
            }
            cout << endl;
        }
    } while (next_permutation(digits.begin(), digits.end()));
    return 0;
}
```
The program first extracts the digits of the given number and sorts them in ascending order. It then generates all possible permutations of the digits and checks if the difference between any two consecutive numbers is a prime number. If so, it prints out the permutation in descending order.

