class Patient {
  constructor(name, diagnosis, allergies) {
    this.name = name;
    this.diagnosis = diagnosis;
    this.allergies = allergies;
  }
}
//create an array of patient objects
let patients = [
  new Patient("John Smith", "Cancer", ["penicillin", "aspirin"]),
  new Patient("John Smithe", "Arthritis", ["ibuprofen"]),
  new Patient("Johnny Smith", "Cancer", ["penicillin"]),
  new Patient("Jane Doe", "Asthma", ["aspirin"])
];
// function to check if a patient is allergic to a drug
function checkAllergy(patient, drug) {
  for (let i = 0; i < patient.allergies.length; i++) {
    if (patient.allergies[i] === drug) {
      return true;
    }
  }
  return false;
}
// function to send alert to dispensing system to stop giving drug
function sendAlert(patient, drug) {
  console.log(`Alert sent to dispensing system to stop giving ${drug} to ${patient.name}`);
}
// loop through patients and check for allergies to drug
function checkPatientsForAllergy(patients, drug) {
  for (let i = 0; i < patients.length; i++) {
    let patient = patients[i];
    if (checkAllergy(patient, drug)) {
      sendAlert(patient, drug);
    } else {
      //check for patients with similar names or diagnoses
      for (let j = 0; j < patients.length; j++) {
        let otherPatient = patients[j];
        if (otherPatient.name.includes(patient.name) && otherPatient.diagnosis === patient.diagnosis && !checkAllergy(otherPatient, drug)) {
          console.log(`Patient ${otherPatient.name} has similar name and diagnosis as ${patient.name} but is not allergic to ${drug}`);
